import java.util.*;class Twitter{long tm;Map<Integer,List<long[]>>tw=new HashMap<>();Map<Integer,Set<Integer>>fo=new HashMap<>();public Twitter(){}public void postTweet(int u,int id){tw.computeIfAbsent(u,k->new ArrayList<>()).add(new long[]{tm++,id});}public List<Integer> getNewsFeed(int u){List<long[]>a=new ArrayList<>(tw.getOrDefault(u,List.of()));for(int v:fo.getOrDefault(u,Set.of()))a.addAll(tw.getOrDefault(v,List.of()));a.sort((x,y)->Long.compare(y[0],x[0]));List<Integer>o=new ArrayList<>();for(int i=0;i<a.size()&&i<10;i++)o.add((int)a.get(i)[1]);return o;}public void follow(int a,int b){if(a!=b)fo.computeIfAbsent(a,k->new HashSet<>()).add(b);}public void unfollow(int a,int b){fo.getOrDefault(a,Collections.emptySet()).remove(b);}}
